GRANT USAGE, CREATE ON SCHEMA public TO mqi_demo_public_reader;
ALTER FUNCTION public.mqi_demo_read(text,text,text,text,date,date) OWNER TO mqi_demo_public_reader;
REVOKE CREATE ON SCHEMA public FROM mqi_demo_public_reader;
REVOKE ALL ON FUNCTION public.mqi_demo_read(text,text,text,text,date,date) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.mqi_demo_read(text,text,text,text,date,date) TO anon;
REVOKE mqi_demo_public_reader FROM postgres;
NOTIFY pgrst, 'reload schema';

-- MQI FUNCTION ACL: keep this block last in every migration.
-- Schema-scoped default REVOKE cannot undo PostgreSQL's global PUBLIC EXECUTE.
-- Apply explicit ACLs before this migration transaction commits; no global defaults changed.
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA mqi, mqi_audit FROM PUBLIC;
DO $mqi_function_acl$
DECLARE app_role text;
BEGIN
    FOREACH app_role IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
        IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = app_role) THEN
            EXECUTE format('REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA mqi, mqi_audit FROM %I', app_role);
        END IF;
    END LOOP;
END
$mqi_function_acl$;
